ALTER TABLE dayamora.garment_cutouts ADD COLUMN IF NOT EXISTS source_image TEXT;
CREATE TABLE IF NOT EXISTS dayamora.member_settings(user_id TEXT PRIMARY KEY REFERENCES dayamora.users(id),addresses TEXT NOT NULL DEFAULT '[]',style TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS dayamora.product_watches(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES dayamora.users(id),product_id INTEGER NOT NULL REFERENCES dayamora.products(id),kind TEXT NOT NULL CHECK(kind IN ('price','stock')),variant TEXT NOT NULL,color_id TEXT NOT NULL DEFAULT '',target BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,UNIQUE(user_id,product_id,kind,variant,color_id));
CREATE INDEX IF NOT EXISTS product_watches_owner ON dayamora.product_watches(user_id);
CREATE TABLE IF NOT EXISTS dayamora.return_requests(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES dayamora.users(id),order_id TEXT NOT NULL UNIQUE REFERENCES dayamora.orders(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewing','accepted','rejected','completed')),reply TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS dayamora.community_posts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES dayamora.users(id),caption TEXT NOT NULL,product_ids TEXT NOT NULL,image_url TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','withdrawn')),consented_at BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS community_posts_status ON dayamora.community_posts(status,created_at DESC);
CREATE TABLE IF NOT EXISTS dayamora.coupons(code TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('percent','fixed')),amount BIGINT NOT NULL CHECK(amount>0),min_total BIGINT NOT NULL DEFAULT 0,max_discount BIGINT NOT NULL,expires_at BIGINT NOT NULL,limit_total INTEGER NOT NULL DEFAULT 100,limit_user INTEGER NOT NULL DEFAULT 1,enabled BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS dayamora.coupon_uses(order_id TEXT PRIMARY KEY REFERENCES dayamora.orders(id),user_id TEXT NOT NULL REFERENCES dayamora.users(id),code TEXT NOT NULL REFERENCES dayamora.coupons(code),discount BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS coupon_uses_code_user ON dayamora.coupon_uses(code,user_id);
REVOKE ALL ON dayamora.member_settings,dayamora.product_watches,dayamora.return_requests,dayamora.community_posts,dayamora.coupons,dayamora.coupon_uses FROM PUBLIC;
INSERT INTO dayamora.migrations(version,applied_at) VALUES(5,(extract(epoch FROM now())*1000)::bigint) ON CONFLICT DO NOTHING;
